import React, { lazy } from "react";
import { Switch, Route, Redirect } from "react-router-dom";

import { APP_PREFIX_PATH } from "configs/AppConfig";

const Evidence = () => {
  return (
    <Switch>
      <Redirect
        exact
        from={`${APP_PREFIX_PATH}/evidence`}
        to={`${APP_PREFIX_PATH}/evidence/list`}
      />

      <Route
        path={`${APP_PREFIX_PATH}/evidence/list`}
        component={lazy(() => import(`./evidence-list`))}
      />
      <Route
        path={`${APP_PREFIX_PATH}/evidence/view/:id`}
        component={lazy(() => import(`./evidence-view`))}
      />
    </Switch>
  );
};

export default Evidence;
